'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

if (input.length === 0) process.exit(0);

const n = input[0];
const keys = new Float64Array(n + 1);
const priorities = new Uint32Array(n + 1);
const left = new Int32Array(n + 1);
const right = new Int32Array(n + 1);
const counts = new Int32Array(n + 1);
const sizes = new Int32Array(n + 1);

let used = 0;
let root = 0;

function update(node) {
  sizes[node] = sizes[left[node]] + sizes[right[node]] + counts[node];
}

function rotateRight(node) {
  const child = left[node];
  left[node] = right[child];
  right[child] = node;
  update(node);
  update(child);
  return child;
}

function rotateLeft(node) {
  const child = right[node];
  right[node] = left[child];
  left[child] = node;
  update(node);
  update(child);
  return child;
}

function insert(node, key) {
  if (node === 0) {
    const id = ++used;
    keys[id] = key;
    priorities[id] = (Math.random() * 0x100000000) >>> 0;
    counts[id] = 1;
    sizes[id] = 1;
    return id;
  }

  if (key === keys[node]) {
    counts[node]++;
  } else if (key < keys[node]) {
    left[node] = insert(left[node], key);
    if (priorities[left[node]] < priorities[node]) {
      node = rotateRight(node);
    }
  } else {
    right[node] = insert(right[node], key);
    if (priorities[right[node]] < priorities[node]) {
      node = rotateLeft(node);
    }
  }

  update(node);
  return node;
}

function countAtMost(key) {
  let node = root;
  let result = 0;

  while (node !== 0) {
    if (key < keys[node]) {
      node = left[node];
    } else {
      result += sizes[left[node]] + counts[node];
      node = right[node];
    }
  }

  return result;
}

const output = [];
let previousPenalty = 0;
let pos = 1;

for (let i = 0; i < n; i++) {
  const x = input[pos++] + previousPenalty;
  const y = input[pos++] + previousPenalty;
  const distanceSquared = x * x + y * y;

  const penalty = countAtMost(distanceSquared);
  output.push(String(penalty));

  root = insert(root, distanceSquared);
  previousPenalty = penalty;
}

process.stdout.write(output.join('\n'));
